def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for the full-height and full-width separators.
    sep = None
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            sep = grid[r][0]
            break

    divider_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    divider_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def segments(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    rows = segments(h, divider_rows)
    cols = segments(w, divider_cols)

    # The colored objects in the first tile column specify the color for each tile row.
    row_colors = []
    for r0, r1 in rows:
        counts = {}
        for r in range(r0, r1):
            for c in range(cols[0][0], cols[0][1]):
                v = grid[r][c]
                if v not in (0, sep):
                    counts[v] = counts.get(v, 0) + 1
        row_colors.append(max(counts, key=counts.get))

    marker_colors = set(row_colors)

    # Find the separate tile containing the pattern to be copied.
    motif = None
    for r0, r1 in rows:
        for c0, c1 in cols[1:]:
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v not in (0, sep) and v not in marker_colors:
                        counts[v] = counts.get(v, 0) + 1
            if counts:
                color = max(counts, key=counts.get)
                motif = [
                    [grid[r][c] == color for c in range(c0, c1)]
                    for r in range(r0, r1)
                ]
                break
        if motif is not None:
            break

    out = [[sep if r in divider_rows or c in divider_cols else 0
            for c in range(w)] for r in range(h)]

    for i, (r0, r1) in enumerate(rows):
        for c0, c1 in cols:
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    if motif[dr][dc]:
                        out[r0 + dr][c0 + dc] = row_colors[i]

    return out
